# Terraform Module for S3 + RDS + IAM

I'll provide a complete, production-ready Terraform module structure for dev/prod environments using `.tfvars` files (idiomatic Terraform environment separation).

## Module Structure

```
├── modules/
│   ├── s3/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   ├── rds/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   └── iam/
│       ├── main.tf
│       ├── variables.tf
│       └── outputs.tf
├── main.tf
├── variables.tf
├── outputs.tf
├── dev.tfvars
├── prod.tfvars
├── backend.tf
└── terraform.tfvars
```

---

## `modules/s3/main.tf`

```hcl
# S3 bucket with versioning and encryption
resource "aws_s3_bucket" "app_bucket" {
  bucket = var.bucket_name

  tags = merge(
    var.common_tags,
    {
      Name = var.bucket_name
    }
  )
}

# Block public access
resource "aws_s3_bucket_public_access_block" "app_bucket" {
  bucket = aws_s3_bucket.app_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Enable versioning
resource "aws_s3_bucket_versioning" "app_bucket" {
  bucket = aws_s3_bucket.app_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Server-side encryption (KMS for prod, AES-256 for dev)
resource "aws_s3_bucket_server_side_encryption_configuration" "app_bucket" {
  bucket = aws_s3_bucket.app_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm      = var.use_kms_encryption ? "aws:kms" : "AES256"
      kms_master_key_id  = var.use_kms_encryption ? aws_kms_key.s3_key[0].arn : null
    }
    bucket_key_enabled = var.use_kms_encryption ? true : false
  }
}

# KMS key for prod
resource "aws_kms_key" "s3_key" {
  count                   = var.use_kms_encryption ? 1 : 0
  description             = "KMS key for S3 bucket ${var.bucket_name}"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = merge(
    var.common_tags,
    { Name = "${var.bucket_name}-kms" }
  )
}

resource "aws_kms_alias" "s3_key" {
  count         = var.use_kms_encryption ? 1 : 0
  name          = "alias/${var.bucket_name}"
  target_key_id = aws_kms_key.s3_key[0].key_id
}

# Cross-region replication (prod only)
resource "aws_s3_bucket_replication_configuration" "app_bucket" {
  count  = var.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.app_bucket.id

  depends_on = [aws_s3_bucket_versioning.app_bucket]

  role = aws_iam_role.replication[0].arn

  rule {
    id       = "replicate-all"
    status   = "Enabled"
    priority = 1

    destination {
      bucket       = "arn:aws:s3:::${var.replication_bucket_name}"
      storage_class = "STANDARD"

      replication_time {
        status = "Enabled"
        time {
          minutes = 15
        }
      }

      metrics {
        status = "Enabled"
        event_threshold {
          minutes = 15
        }
      }
    }
  }
}

resource "aws_iam_role" "replication" {
  count = var.enable_replication ? 1 : 0
  name  = "${var.bucket_name}-replication"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })

  tags = var.common_tags
}

resource "aws_iam_role_policy" "replication" {
  count  = var.enable_replication ? 1 : 0
  name   = "${var.bucket_name}-replication-policy"
  role   = aws_iam_role.replication[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.app_bucket.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl"
        ]
        Resource = "${aws_s3_bucket.app_bucket.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete"
        ]
        Resource = "arn:aws:s3:::${var.replication_bucket_name}/*"
      }
    ]
  })
}
```

