## `modules/rds/main.tf`

```hcl
# KMS key for RDS encryption
resource "aws_kms_key" "rds_key" {
  description             = "KMS key for RDS encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = merge(
    var.common_tags,
    { Name = "${var.db_identifier}-kms" }
  )
}

resource "aws_kms_alias" "rds_key" {
  name          = "alias/${var.db_identifier}"
  target_key_id = aws_kms_key.rds_key.key_id
}

# DB subnet group
resource "aws_db_subnet_group" "app_db" {
  name       = "${var.db_identifier}-subnet-group"
  subnet_ids = var.db_subnet_ids

  tags = merge(
    var.common_tags,
    { Name = "${var.db_identifier}-subnet-group" }
  )
}

# Security group for RDS
resource "aws_security_group" "rds" {
  name_prefix = "${var.db_identifier}-"
  description = "Security group for ${var.db_identifier} RDS instance"
  vpc_id      = var.vpc_id

  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = var.allowed_security_groups
    description     = "PostgreSQL access from app servers"
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    description = "Allow all outbound traffic"
  }

  tags = merge(
    var.common_tags,
    { Name = "${var.db_identifier}-sg" }
  )

  lifecycle {
    create_before_destroy = true
  }
}

# RDS PostgreSQL instance
resource "aws_db_instance" "app_db" {
  identifier     = var.db_identifier
  engine         = "postgres"
  engine_version = var.db_engine_version

  instance_class    = var.db_instance_class
  allocated_storage = var.db_allocated_storage
  storage_type      = "gp3"
  storage_encrypted = true
  kms_key_id        = aws_kms_key.rds_key.arn

  db_name  = var.db_name
  username = var.db_username
  # Password should be managed via AWS Secrets Manager (see IAM module)
  password = var.db_password

  db_subnet_group_name            = aws_db_subnet_group.app_db.name
  vpc_security_group_ids          = [aws_security_group.rds.id]
  multi_az                        = var.db_multi_az
  publicly_accessible             = false
  deletion_protection             = var.enable_deletion_protection
  backup_retention_period          = var.backup_retention_days
  backup_window                   = "03:00-04:00"
  maintenance_window              = "sun:04:00-sun:05:00"
  auto_minor_version_upgrade      = true
  copy_tags_to_snapshot           = true
  skip_final_snapshot             = var.skip_final_snapshot
  final_snapshot_identifier       = !var.skip_final_snapshot ? "${var.db_identifier}-final-snapshot-${formatdate("YYYY-MM-DD-hhmm", timestamp())}" : null
  enable_cloudwatch_logs_exports  = ["postgresql"]
  enable_enhanced_monitoring      = var.enable_enhanced_monitoring
  monitoring_interval             = var.enable_enhanced_monitoring ? 60 : 0
  monitoring_role_arn             = var.enable_enhanced_monitoring ? aws_iam_role.rds_monitoring[0].arn : null
  enable_iam_database_authentication = true
  delete_automated_backups        = false

  tags = merge(
    var.common_tags,
    { Name = var.db_identifier }
  )
}

# Enhanced monitoring role (optional, for prod)
resource "aws_iam_role" "rds_monitoring" {
  count = var.enable_enhanced_monitoring ? 1 : 0
  name  = "${var.db_identifier}-monitoring"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "monitoring.rds.amazonaws.com"
      }
    }]
  })

  tags = var.common_tags
}

resource "aws_iam_role_policy_attachment" "rds_monitoring" {
  count      = var.enable_enhanced_monitoring ? 1 : 0
  role       = aws_iam_role.rds_monitoring[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}
```

