## `modules/iam/main.tf`

```hcl
# IAM role for service account
resource "aws_iam_role" "service_account" {
  name_prefix = "${var.role_name}-"
  description = "Service account role for ${var.role_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Principal" = var.trust_policy_principal
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(
    var.common_tags,
    { Name = var.role_name }
  )
}

# Policy for S3 access
resource "aws_iam_role_policy" "s3_access" {
  name_prefix = "${var.role_name}-s3-"
  role        = aws_iam_role.service_account.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:ListBucket"
        ]
        Resource = [
          var.s3_bucket_arn,
          "${var.s3_bucket_arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:PutObjectAcl"
        ]
        Resource = "${var.s3_bucket_arn}/*"
        # For prod, add condition to prevent public ACLs
        Condition = var.environment == "prod" ? {
          StringEquals = {
            "s3:x-amz-acl" = ["private", "aws-exec-read"]
          }
        } : {}
      }
    ]
  })
}

# Policy for RDS IAM auth (if enabled)
resource "aws_iam_role_policy" "rds_iam_auth" {
  count       = var.enable_rds_iam_auth ? 1 : 0
  name_prefix = "${var.role_name}-rds-"
  role        = aws_iam_role.service_account.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "rds-db:connect"
        ]
        Resource = [
          "arn:aws:rds:${var.aws_region}:${data.aws_caller_identity.current.account_id}:db:${var.rds_db_resource_id}"
        ]
        Condition = {
          StringEquals = {
            "aws:userid" = "*:${var.role_name}"
          }
        }
      }
    ]
  })
}

# Policy for Secrets Manager access (database credentials)
resource "aws_iam_role_policy" "secrets_access" {
  count       = var.enable_secrets_access ? 1 : 0
  name_prefix = "${var.role_name}-secrets-"
  role        = aws_iam_role.service_account.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = [
          "arn:aws:secretsmanager:${var.aws_region}:${data.aws_caller_identity.current.account_id}:secret:${var.role_name}/*"
        ]
      }
    ]
  })
}

# KMS access for encrypted secrets
resource "aws_iam_role_policy" "kms_access" {
  count       = var.enable_secrets_access ? 1 : 0
  name_prefix = "${var.role_name}-kms-"
  role        = aws_iam_role.service_account.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = [
          var.kms_key_arns
        ]
      }
    ]
  })
}

# Data source for current AWS account ID
data "aws_caller_identity" "current" {}

# Optional: Create access key for programmatic access (dev only)
resource "aws_iam_access_key" "service_account" {
  count   = var.create_access_key ? 1 : 0
  user    = aws_iam_user.service_account[0].name
  depends_on = [
    aws_iam_user_policy.service_account[0]
  ]
}

resource "aws_iam_user" "service_account" {
  count = var.create_access_key ? 1 : 0
  name  = "${var.role_name}-user"
  tags  = var.common_tags
}

resource "aws_iam_user_policy" "service_account" {
  count       = var.create_access_key ? 1 : 0
  name_prefix = "${var.role_name}-"
  user        = aws_iam_user.service_account[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          var.s3_bucket_arn,
          "${var.s3_bucket_arn}/*"
        ]
      }
    ]
  })
}
```

