  description = "Enable IAM database authentication for RDS"
  type        = bool
  default     = true
}

variable "rds_db_resource_id" {
  description = "RDS database resource ID"
  type        = string
}

variable "enable_secrets_access" {
  description = "Enable Secrets Manager access"
  type        = bool
  default     = true
}

variable "kms_key_arns" {
  description = "List of KMS key ARNs for decryption"
  type        = list(string)
  default     = []
}

