  description = "Principal for assume role trust policy"
  type        = any
  default = {
    Service = "ec2.amazonaws.com"
  }
}

variable "create_access_key" {
  description = "Create IAM access key for programmatic access (dev only)"
  type        = bool
  default     = false
}

variable "common_tags" {
  description = "Common tags to apply to all resources"
  type        = map(string)
  default     = {}
}
```

