## Root Configuration: `main.tf`

```hcl
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  backend "s3" {
    # Configure via backend config file or environment variables
    # bucket         = "terraform-state-bucket"
    # key            = "app-infrastructure/terraform.tfstate"
    # region         = "us-east-1"
    # encrypt        = true
    # dynamodb_table = "terraform-locks"
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Terraform   = "true"
      Environment = var.environment
      Project     = var.project_name
    }
  }
}

# S3 Module
module "s3" {
  source = "./modules/s3"

  bucket_name           = var.s3_bucket_name
  use_kms_encryption    = var.environment == "prod"
  enable_replication    = var.environment == "prod" ? var.enable_s3_replication : false
  replication_bucket_name = var.replication_bucket_name

  common_tags = {
    Module = "s3"
  }
}

# RDS Module
module "rds" {
  source = "./modules/rds"

  db_identifier             = var.db_identifier
  db_name                   = var.db_name
  db_username               = var.db_username
  db_password               = var.db_password
  db_instance_class         = var.db_instance_class
  db_allocated_storage      = var.db_allocated_storage
  db_multi_az               = var.environment == "prod" ? true : false
  db_subnet_ids             = var.db_subnet_ids
  vpc_id                    = var.vpc_id
  allowed_security_groups   = var.app_security_group_ids
  backup_retention_days     = var.backup_retention_days
  enable_deletion_protection = true
  skip_final_snapshot       = var.environment == "dev" ? true : false
  enable_enhanced_monitoring = var.environment == "prod" ? true : false

  common_tags = {
    Module = "rds"
  }
}

# IAM Module
module "iam" {
  source = "./modules/iam"

  role_name              = var.service_account_role_name
  environment            = var.environment
  aws_region             = var.aws_region
  s3_bucket_arn          = module.s3.bucket_arn
  rds_db_resource_id     = module.rds.db_instance_id
  enable_rds_iam_auth    = true
  enable_secrets_access  = true
  kms_key_arns           = [module.rds.db_kms_key_id]
  create_access_key      = var.environment == "dev" && var.create_access_key
  trust_policy_principal = var.iam_trust_principal

  common_tags = {
    Module = "iam"
  }
}

# Store DB credentials in Secrets Manager (encrypted)
resource "aws_secretsmanager_secret" "db_credentials" {
  name_prefix             = "${var.db_identifier}-credentials-"
  description             = "Database credentials for ${var.db_identifier}"
  recovery_window_in_days = 7
  kms_key_id              = module.rds.db_kms_key_id

  tags = {
    Name = "${var.db_identifier}-credentials"
  }
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = var.db_username
    password = var.db_password
    engine   = "postgres"
    host     = module.rds.db_instance_address
    port     = module.rds.db_instance_port
    dbname   = var.db_name
  })
}

resource "aws_secretsmanager_secret_policy" "db_credentials" {
  secret_arn = aws_secretsmanager_secret.db_credentials.arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = module.iam.role_arn
        }
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = "*"
      }
    ]
  })
}
```

